import app from 'flarum/forum/app';
import extractText from 'flarum/common/utils/extractText';
import { tx } from './api';

/*
 * Talking to the server, the shared card cache and formatting: only the lazy
 * chunk needs these, so they stay out of forum.js.
 */

/** The sentence for an error answer from our endpoints (a field's own rule says what's wrong in `detail`). */
export function errorText(error) {
  const first = error?.response?.errors?.[0];
  const code = first?.code;
  const key = `ernestdefoe-predictions.forum.errors.${code}`;
  if (code && extractText(app.translator.trans(key)) !== key) return extractText(app.translator.trans(key));
  if (code === 'validation_error' && first?.detail) return String(first.detail);
  if (error?.status === 0) return extractText(app.translator.trans('core.lib.error.network_message'));
  if (error?.status === 403) return extractText(app.translator.trans('core.lib.error.permission_denied_message'));
  return tx('errors.generic');
}
/**
 * A request to our endpoints. Every write to a prediction takes its lock without
 * waiting, so a write that meets another one at the same instant is answered 409
 * `predictions_busy`: it's tried once more a moment later before the reader is told.
 */
export function call(method, path, data, retry = method !== 'GET') {
  const url = app.forum.attribute('apiUrl') + path;
  return app.request({
    method,
    url: method === 'GET' && data ? url + '?' + query(data) : url,
    body: method === 'GET' ? undefined : data,
    errorHandler: error => {
      throw error;
    }
  }).catch(error => {
    if (retry && error?.response?.errors?.[0]?.code === 'predictions_busy') {
      return new Promise(resolve => window.setTimeout(resolve, 400)).then(() => call(method, path, data, false));
    }
    app.alerts.show({
      type: 'error'
    }, errorText(error));
    throw error;
  });
}

/** filter[status]=open style parameters from a nested object. */
function query(data, prefix = '') {
  return Object.entries(data).filter(([, value]) => value !== undefined && value !== null && value !== '').map(([key, value]) => {
    const name = prefix ? `${prefix}[${key}]` : key;
    return typeof value === 'object' ? query(value, name) : `${encodeURIComponent(name)}=${encodeURIComponent(String(value))}`;
  }).join('&');
}
export function person(user) {
  if (!user) return null;
  return {
    id: Number(user.id()),
    username: user.username(),
    displayName: user.displayName(),
    slug: user.slug(),
    avatarUrl: user.avatarUrl() || null
  };
}

/**
 * A stored prediction as the plain object cards read. Relationships only when the
 * response carried them (an action's response has the attributes alone), so a
 * refresh after a pick never blanks the creator or the discussion.
 */
function plain(model) {
  const attributes = model.data.attributes;
  const related = model.data.relationships || {};
  const discussion = model.discussion();
  return {
    ...attributes,
    id: Number(model.id()),
    type: attributes.kind,
    ...('user' in related ? {
      user: person(model.user())
    } : {}),
    ...('discussion' in related ? {
      discussion: discussion ? {
        id: Number(discussion.id()),
        title: discussion.title(),
        slug: discussion.slug()
      } : null
    } : {})
  };
}

/** A JSON:API answer pushed into the store and turned into plain predictions. */
function store(doc) {
  const models = app.store.pushPayload(doc);
  return (Array.isArray(models) ? models : [models]).map(model => remember(plain(model)));
}

/**
 * Every prediction a page shows is fetched once and shared: the same card in
 * a post and on the discussion stays in step when someone picks. Embeds ask
 * for theirs together (one request for all the links on a page).
 */
const known = new Map();
let wanted = new Map();
let timer = 0;
export function remember(prediction) {
  const existing = known.get(prediction.id);
  if (existing) {
    Object.assign(existing, prediction);
    return existing;
  }
  known.set(prediction.id, prediction);
  return prediction;
}
export function forget(id) {
  known.delete(id);
}
export function lookup(id) {
  const found = known.get(id);
  if (found) return Promise.resolve(found);
  return new Promise(resolve => {
    wanted.set(id, [...(wanted.get(id) || []), resolve]);
    timer ||= window.setTimeout(flush, 0);
  });
}
function flush() {
  const batch = wanted;
  wanted = new Map();
  timer = 0;
  const ids = [...batch.keys()];
  for (let i = 0; i < ids.length; i += 50) {
    const chunk = ids.slice(i, i + 50);
    const answer = found => chunk.forEach(id => batch.get(id).forEach(resolve => resolve(found(id))));
    app.request({
      method: 'GET',
      url: app.forum.attribute('apiUrl') + '/predictions?' + query({
        filter: {
          id: chunk.join(',')
        },
        page: {
          limit: 50
        }
      })
    }).then(doc => {
      store(doc);
      answer(id => known.get(id) || null);
    },
    // A card that can't be loaded leaves its link a link.
    () => answer(() => null));
  }
}
export function list(filter, offset = 0, limit = 20) {
  return call('GET', '/predictions', {
    filter,
    page: {
      offset,
      limit
    }
  }).then(doc => ({
    data: store(doc),
    more: !!doc.links?.next
  }));
}

/**
 * Open (id null) or edit a prediction. The form's `type` is sent as `kind` (JSON:API
 * reserves `type`), and the discussion it belongs to as a relationship, only when opening.
 */
export function save(id, body) {
  const {
    type,
    discussionId,
    ...rest
  } = body;
  const attributes = type === undefined ? rest : {
    ...rest,
    kind: type
  };
  const relationships = !id && discussionId ? {
    discussion: {
      data: {
        type: 'discussions',
        id: String(discussionId)
      }
    }
  } : undefined;
  const data = {
    type: 'predictions',
    ...(id ? {
      id: String(id)
    } : {}),
    attributes,
    ...(relationships ? {
      relationships
    } : {})
  };
  return call(id ? 'PATCH' : 'POST', id ? `/predictions/${id}` : '/predictions', {
    data
  }).then(doc => store(doc)[0]);
}
export function pick(id, body) {
  return call(body ? 'POST' : 'DELETE', `/predictions/${id}/pick`, body || undefined).then(doc => store(doc)[0]);
}
export function settle(id, body) {
  return call('POST', `/predictions/${id}/settle`, body).then(doc => store(doc)[0]);
}
export function remove(id) {
  return call('DELETE', `/predictions/${id}`).then(() => forget(id));
}

/** Who picked what, best results first, once picks are out in the open: a page at a time. */
export function pickers(id, offset = 0) {
  return call('GET', '/prediction-picks', {
    filter: {
      prediction: id
    },
    include: 'user',
    page: {
      offset,
      limit: 100,
      total: 0
    }
  }).then(doc => ({
    rows: app.store.pushPayload(doc).map(row => ({
      optionId: row.optionId(),
      value: row.value(),
      hit: row.hit(),
      points: row.points(),
      user: person(row.user())
    })).filter(row => row.user !== null),
    more: !!doc.links?.next
  }));
}
function standing(row) {
  const user = person(row.user());
  return user && {
    rank: row.rank(),
    user,
    points: row.points(),
    hits: row.hits(),
    settled: row.settled(),
    hitRate: row.hitRate(),
    streak: row.streak(),
    bestStreak: row.bestStreak(),
    oracle: row.oracle()
  };
}

/**
 * The leaderboard for a season ('all' for all time, undefined for the running one), and
 * the viewer's own row and rank in it (a second, one-row request), even when off the board.
 */
export function board(season, limit = 50) {
  const ask = (filter, size) => call('GET', '/prediction-standings', {
    filter,
    page: {
      limit: size,
      total: 0
    }
  });
  const me = app.session.user;
  return ask({
    season
  }, limit).then(doc => {
    const rows = app.store.pushPayload(doc).map(standing).filter(row => row !== null);
    const result = {
      ...doc.meta,
      rows,
      me: null,
      oracles: rows.filter(row => row.oracle)
    };
    const mine = me && rows.find(row => row.user.id === Number(me.id()));
    if (!me || mine) return {
      ...result,
      me: mine || null
    };
    return ask({
      season: season ?? doc.meta.season?.id,
      user: me.id()
    }, 1).then(own => ({
      ...result,
      me: app.store.pushPayload(own).map(standing)[0] || null
    }));
  });
}

/** "1,234.5" in the reader's language, keeping up to 2 decimals. */
export function num(value) {
  if (value === null || value === undefined) return '';
  return new Intl.NumberFormat(app.translator.getLocale() || undefined, {
    maximumFractionDigits: 2
  }).format(value);
}

/** "2d 4h", "3h 12m", "45m", "under a minute" until the lock. */
export function countdown(iso) {
  const ms = new Date(iso).getTime() - Date.now();
  if (ms <= 60000) return tx('time.soon');
  const minutes = Math.floor(ms / 60000);
  const days = Math.floor(minutes / 1440);
  const hours = Math.floor(minutes % 1440 / 60);
  const mins = minutes % 60;
  if (days) return tx('time.days_hours', {
    days,
    hours
  });
  if (hours) return tx('time.hours_minutes', {
    hours,
    minutes: mins
  });
  return tx('time.minutes', {
    minutes: mins
  });
}
export function when(iso) {
  return new Intl.DateTimeFormat(app.translator.getLocale() || undefined, {
    dateStyle: 'medium',
    timeStyle: 'short'
  }).format(new Date(iso));
}